#pragma once

// Public type definitions
typedef struct {
    long long num;
    unsigned char len;
} zfloat;

// Public function interfaces (signatures)
double _zTod(zfloat d);
zfloat _f(char *floatNumber);
int _flen(zfloat d);
zfloat _add(zfloat fd, zfloat sd);
zfloat _mul(zfloat fd, zfloat sd);
zfloat _sub(zfloat fd, zfloat sd);
void print_f(zfloat d, int expand_digit);

#include "_float.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// 0.5v
double _zTod(zfloat d) {
    return (double)d.num / pow(10.0, d.len);
}

long long ipow10(int exp) {
    long long result = 1;
    for (int i = 0; i < exp; i++) {
        result *= 10;
    }
    return result;
}

zfloat _f(char *floatNumberImp) {
    zfloat d = {0};
    int x = 0;
    int sing = 1;

    char *floatNumber = floatNumberImp;

    if (floatNumber[0] == '-') {
        floatNumber = &floatNumber[1];
        sing = -1;
    }

    while (floatNumber[x] != '\0' && floatNumber[x] != '.') {
        d.num = (d.num * 10) + (floatNumber[x] - '0');
        x++;
    }

    if (floatNumber[x] == '.') {
        x++;
    }

    int y = 0;
    while (floatNumber[x] != '\0') {
        d.num = (d.num * 10) + (floatNumber[x] - '0');
        x++;
        y++;
    }

    d.num = d.num * sing;
    d.len = y;

    return d;
}

int _flen(zfloat d) {
    if (d.num == 0) {
        return 1;
    }

    int result = (int)log10(llabs(d.num)) + 1;
    if (result <= d.len) {
        result = d.len + 1;
    }

    return result;
}

zfloat _add(zfloat fd, zfloat sd) {
    zfloat result = {0};

    if (fd.len == sd.len) {
        result.num = fd.num + sd.num;
        result.len = fd.len;
        return result;
    }

    int moredigitCount = fd.len - sd.len;
    if (moredigitCount > 0) {
        int shift = ipow10(moredigitCount);
        sd.num = sd.num * shift;
        result.num = fd.num + sd.num;
        result.len = fd.len;
        return result;
    } else {
        moredigitCount = moredigitCount * -1;
        int shift = ipow10(moredigitCount);
        fd.num = fd.num * shift;
        result.num = sd.num + fd.num;
        result.len = sd.len;
        return result;
    }
}

zfloat _mul(zfloat fd, zfloat sd) {
    zfloat result = {0};
    result.num = fd.num * sd.num;
    result.len = fd.len + sd.len;
    return result;
}

zfloat _sub(zfloat fd, zfloat sd) {
    zfloat result = {0};

    if (fd.len == sd.len) {
        result.num = fd.num - sd.num;
        result.len = fd.len;
        return result;
    }

    int moredigitCount = fd.len - sd.len;
    if (moredigitCount > 0) {
        int shift = ipow10(moredigitCount);
        sd.num = sd.num * shift;
        result.num = fd.num - sd.num;
        result.len = fd.len;
        return result;
    } else {
        moredigitCount = moredigitCount * -1;
        int shift = ipow10(moredigitCount);
        fd.num = fd.num * shift;
        result.num = fd.num - sd.num;
        result.len = sd.len;
        return result;
    }
}

void print_f(zfloat d, int expand_digit) {
    char floatNumberImp[32];
    char *floatNumber = floatNumberImp;
    memset(floatNumber, '0', sizeof(floatNumber));

    long long temp = d.num;
    if (d.num < 0) {
        floatNumber[0] = '-';
        floatNumber = &floatNumber[1];
        temp = temp * - 1;
    }

    int total_digits = _flen(d);

    if (total_digits >= 30) {
        return;
    }

    // Handle edge case where number is pure fractional (e.g., 0.5)
    // If our digit length is smaller or equal to the fraction requirement,
    // we need to account for a leading zero digit space
    if (total_digits <= d.len) {
        total_digits = d.len + 1;
    }

    int string_length = total_digits + 1; // Number layout length + dot room

    // Fixed Bug 3: Walk backward, dropping the dot based on fractional spacing from the right side
    int fraction_counter = 0;
    for (int i = string_length - 1; i >= 0; i--) {
        if (fraction_counter == d.len && floatNumber[i + 1] != '.') {
            floatNumber[i] = '.';
            i--; // Shift index step left to stay aligned
        }

        int digit = temp % 10;
        floatNumber[i] = digit + '0';
        temp = temp / 10;
        fraction_counter++;
    }

    string_length = ((string_length + expand_digit) > 31) ? 31 : (string_length + expand_digit);
    floatNumber[string_length] = '\0';
    printf("%s\n", floatNumberImp);
}

USAGE:


int main()
{
    float money = 0;

    for(int i=0;i<100;i++)
    {
        money += 0.01f;
    }

    printf("%.20f\n", money);

    zfloat money2 = _f("0");

    for(int i=0;i<100;i++)
    {
        money2 = _add(money2, _f("0.01"));
    }

    print_f(money2, 0);

    return 0;
}

